      "proposed_laureates": [
        "Christopher Jarzynski",
        "Denis J. Evans",
        "Udo Seifert"
      ],
      "assessment": {
        "nobel_worthiness": "The fluctuation relations exposed a remarkably simple and general structure governing irreversibility far from equilibrium.",
        "attribution": "Evans established the early fluctuation theorem, Jarzynski its transformative work relation, and Seifert developed a coherent stochastic-thermodynamic framework.",
        "maturity": "The relations are theoretically understood, experimentally tested across many systems, and central to modern nonequilibrium statistical physics.",
        "uncertainties": [
          "Crooks also made a major independent foundational contribution, making a three-person allocation difficult."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B006",
      "proposed_laureates": [
        "Bertrand I. Halperin",
        "David R. Nelson",
        "A. Peter Young"
      ],
      "assessment": {
        "nobel_worthiness": "The defect-mediated theory of two-dimensional melting supplied a deep universal mechanism for an apparently material-specific transition.",
        "attribution": "Halperin, Nelson, and Young jointly formulated the essential KTHNY picture and its renormalization-group consequences.",
        "maturity": "Decades of simulations and experiments have made the hexatic phase and its defect physics a mature cornerstone of statistical physics.",
        "uncertainties": [
          "The detailed phenomenology varies across experimental realizations, including cases with first-order behavior."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B030",
      "proposed_laureates": [
        "Alexander A. Belavin",
        "Alexander B. Zamolodchikov",
        "Alexander M. Polyakov"
      ],
      "assessment": {
        "nobel_worthiness": "Two-dimensional conformal field theory gave exact control of critical phenomena and changed the working language of statistical and quantum field theory.",
        "attribution": "The BPZ work and Polyakov's foundational contributions provide a clear intellectual core for the cited advance.",
        "maturity": "Its conceptual and calculational impact has endured for decades, from critical systems to string theory.",
        "uncertainties": [
          "Credit necessarily compresses a broad community that developed conformal methods."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B017",
      "proposed_laureates": [
        "Antoine Georges",
        "Gabriel Kotliar",
        "Dieter Vollhardt"
      ],
      "assessment": {
        "nobel_worthiness": "Dynamical mean-field theory made strong local electronic correlations quantitatively tractable and connected a clean limiting theory to real materials.",
        "attribution": "Vollhardt and collaborators developed the infinite-dimensional foundation, while Georges and Kotliar established the influential practical formulation.",
        "maturity": "DMFT and its extensions are standard tools with extensive numerical, spectroscopic, and materials validation.",
        "uncertainties": [
          "The relative credit for foundational formulations and later computational implementation is not wholly separable."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B040",
      "proposed_laureates": [
        "Alan H. Guth",
        "Andrei Linde",
        "Viatcheslav Mukhanov"
      ],
      "assessment": {
        "nobel_worthiness": "Inflation and the quantum origin of primordial fluctuations offer an exceptionally powerful account of the observed large-scale universe.",
        "attribution": "Guth initiated inflation, Linde supplied decisive developments, and Mukhanov provided central fluctuation theory linking it to observations.",
        "maturity": "CMB and large-scale-structure observations strongly support key predictions, and the framework is mature.",
        "uncertainties": [
          "The underlying inflationary mechanism and unique model-level predictions remain unsettled."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B021",
      "proposed_laureates": [
        "Peter W. Shor",
        "Andrew M. Steane",
        "Alexei Kitaev"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum error correction identified the essential mechanism by which fragile quantum dynamics can support scalable information processing.",
        "attribution": "Shor and Steane introduced seminal codes, while Kitaev supplied a profound topological route to fault tolerance.",
        "maturity": "The principles are rigorously understood and now guide experimentally advancing quantum hardware.",
        "uncertainties": [
          "A large number of foundational contributors makes any three-name attribution incomplete."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B013",
      "proposed_laureates": [
        "Eli Yablonovitch",
        "Sajeev John",
        "John D. Joannopoulos"
      ],
      "assessment": {
        "nobel_worthiness": "Photonic band gaps transferred a powerful condensed-matter organizing principle to light and enabled a major field of structured photonics.",
        "attribution": "John and Yablonovitch articulated the central physical concept, and Joannopoulos made seminal theoretical and design contributions.",
        "maturity": "The field has produced broad experimental realization and durable scientific and technological consequences.",
        "uncertainties": [
          "The boundary between the original band-gap discovery and subsequent nanophotonic engineering is broad."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B009",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks created an extraordinary precision platform that advances timekeeping, metrology, and tests of fundamental physics.",
        "attribution": "Katori originated the magic-wavelength lattice-clock concept and Ye made defining experimental advances.",
        "maturity": "Independent clocks have reached exceptional reproducibility and have demonstrated clear scientific utility.",
        "uncertainties": [
          "Further confirmation of long-term robustness and applications beyond metrology will clarify the full legacy."
        ]
      }
    }
  ]
